'use client'
import { SearchSelect } from './search-select'
import { useState } from 'react'
import { Pencil } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { api, message } from '@/lib/api'
import type { Data, Payment, Product, Source } from '@/lib/types'
import { money, validNumber } from '@/lib/pos'
import { ErrorBox, Field, inputClass, Panel, RupiahField } from './common'

type Props = { data: Data; refresh: () => Promise<void> }
export function Products({ data, refresh, owner }: Props & { owner: boolean }) {
  const empty = { nama: '', sku: '', barcode: '', harga_jual: '', stok_minimum: '0', kategori_id: '', satuan_id: '', aktif: true, is_favorit: false }
  const [form, setForm] = useState(empty); const [editing, setEditing] = useState<number | null>(null)
  const [query, setQuery] = useState('')
  const products = data.products.filter(product => `${product.nama} ${product.sku} ${product.barcode ?? ''}`.toLowerCase().includes(query.trim().toLowerCase()))
  const [busy, setBusy] = useState(false); const [error, setError] = useState(''); const [notice, setNotice] = useState('')
  function edit(p: Product) { setEditing(p.id); setForm({ nama: p.nama, sku: p.sku, barcode: p.barcode ?? '', harga_jual: p.harga_jual.replace(/\.0+$/, ''), stok_minimum: p.stok_minimum, kategori_id: String(p.kategori_id), satuan_id: String(p.satuan_id), aktif: p.aktif, is_favorit: Boolean(p.is_favorit) }) }
  return <div className="mx-auto grid max-w-7xl gap-5 p-5 lg:grid-cols-[400px_1fr]">
    <div className="product-editor space-y-5">{owner ? <><Panel title={editing ? 'Edit Produk' : 'Tambah Produk'} subtitle="Tambahkan kategori dan satuan dari menu Data Master."><ErrorBox>{error}</ErrorBox>{notice && <p role="status" className="my-3 text-sm text-primary">{notice}</p>}<form onSubmit={async e => {
      e.preventDefault(); if (busy) return; setBusy(true); setError(''); setNotice('')
      try { if (!validNumber(form.harga_jual, 2, true) || !validNumber(form.stok_minimum, 3, true)) throw new Error('Harga atau stok minimum tidak valid.')
        await api(`/produk${editing ? `/${editing}` : ''}`, editing ? 'PUT' : 'POST', { ...form, barcode: form.barcode || null, kategori_id: Number(form.kategori_id), satuan_id: Number(form.satuan_id) })
        setForm(empty); setEditing(null); setNotice('Produk tersimpan. Catat stok melalui menu Pembelian.'); await refresh()
      } catch (err) { setError(message(err)) } finally { setBusy(false) }
    }}><fieldset disabled={busy} className="space-y-3"><Field label="Nama produk" value={form.nama} onChange={nama => setForm({ ...form, nama })} required /><Field label="SKU" value={form.sku} onChange={sku => setForm({ ...form, sku })} required /><Field label="Barcode (opsional)" value={form.barcode} onChange={barcode => setForm({ ...form, barcode })} /><RupiahField label="Harga jual" value={form.harga_jual} onChange={harga_jual => setForm({ ...form, harga_jual })} required /><div className="block text-sm font-semibold"><span>Kategori</span><SearchSelect className={inputClass} required value={form.kategori_id} onValueChange={value => setForm({ ...form, kategori_id: value })} aria-label="Kategori"><option value="">Pilih kategori</option>{data.categories.map(c => <option key={c.id} value={c.id}>{c.nama}</option>)}</SearchSelect></div><div className="block text-sm font-semibold"><span>Satuan</span><SearchSelect className={inputClass} required value={form.satuan_id} onValueChange={value => setForm({ ...form, satuan_id: value })} aria-label="Satuan"><option value="">Pilih satuan</option>{data.units.map(c => <option key={c.id} value={c.id}>{c.nama}</option>)}</SearchSelect></div><label className="flex gap-2"><input type="checkbox" checked={form.aktif} onChange={e => setForm({ ...form, aktif: e.target.checked })} />Produk aktif</label><label className="flex gap-2"><input type="checkbox" checked={form.is_favorit} onChange={e => setForm({ ...form, is_favorit: e.target.checked })} />Favorit toko (semua pengguna)</label><div className="flex flex-col gap-2"><Button type="submit" className="h-12 w-full" disabled={busy}>{busy ? 'Menyimpan…' : 'Simpan Produk'}</Button>{editing && <Button type="button" className="h-12 w-full" variant="outline" disabled={busy} onClick={() => { setEditing(null); setForm(empty) }}>Batal Edit</Button>}</div></fieldset></form></Panel>
</> : <Panel title="Informasi Produk"><p>Perubahan produk dan stok hanya dapat dilakukan pemilik.</p></Panel>}</div>
    <Panel title="Daftar Produk" subtitle={`${data.products.length} produk dari database`}><Field label="Cari daftar produk" value={query} onChange={setQuery} /><div className="divide-y">{products.map(p => <article key={p.id} className="flex flex-wrap items-center justify-between gap-3 py-4"><div><h3 className="font-bold">{p.nama} {p.is_favorit && <span className="text-amber-500" title="Favorit toko">★</span>} {!p.aktif && '(nonaktif)'}</h3><p className="text-sm text-muted-foreground">{p.sku} · {p.barcode ?? 'Tanpa barcode'}</p></div><div className="flex items-center gap-3"><strong>{money(p.harga_jual)}</strong>{owner && <Button type="button" variant="outline" className="size-10" size="icon" aria-label={`Edit ${p.nama}`} title={`Edit ${p.nama}`} onClick={() => edit(p)}><Pencil className="size-4" /></Button>}</div></article>)}{!data.products.length && <p className="py-8 text-muted-foreground">Belum ada produk.</p>}</div></Panel>
  </div>
}

export function Masters({ data, refresh }: Props) {
  const [tab, setTab] = useState('simple')
  return <div className="mx-auto max-w-6xl space-y-5 p-5"><nav className="flex flex-wrap gap-2" aria-label="Data master">{[['simple','Kategori & Satuan'], ['sources','Tempat Beli / Sales'], ['payments','Metode Pembayaran']].map(([key,label]) => <Button key={key} variant={tab === key ? 'default' : 'outline'} onClick={() => setTab(key)}>{label}</Button>)}</nav>{tab === 'simple' && <div className="grid gap-5 md:grid-cols-2"><SimpleMaster kind="kategori" rows={data.categories} refresh={refresh} /><SimpleMaster kind="satuan" rows={data.units} refresh={refresh} /></div>}{tab === 'sources' && <Sources data={data} refresh={refresh} />}{tab === 'payments' && <Payments data={data} refresh={refresh} />}</div>
}
function SimpleMaster({ kind, rows, refresh }: { kind: string; rows: { id: number; nama: string }[]; refresh: () => Promise<void> }) {
  const [name, setName] = useState(''); const [error, setError] = useState(''); const [busy, setBusy] = useState(false)
  return <Panel title={kind === 'kategori' ? 'Kategori' : 'Satuan'}><ErrorBox>{error}</ErrorBox><form className="mb-5 space-y-3" onSubmit={async e => { e.preventDefault(); if (busy) return; setBusy(true); setError(''); try { await api(`/${kind}`, 'POST', { nama: name }); setName(''); await refresh() } catch (err) { setError(message(err)) } finally { setBusy(false) } }}><Field label={`Nama ${kind}`} value={name} onChange={setName} required /><Button type="submit" disabled={busy}>Tambah {kind}</Button></form><ul className="divide-y">{rows.map(row => <li key={row.id} className="py-3">{row.nama}</li>)}</ul></Panel>
}
function Sources({ data, refresh }: Props) {
  const empty = { nama: '', jenis: 'TOKO', nama_toko_perusahaan: '', nama_kontak: '', nomor_telepon: '', alamat: '', catatan: '', aktif: true }
  const [form, setForm] = useState(empty); const [id, setID] = useState<number | null>(null); const [busy, setBusy] = useState(false); const [error, setError] = useState('')
  function edit(row: Source) { setID(row.id); setForm({ nama: row.nama, jenis: row.jenis, nama_toko_perusahaan: row.nama_toko_perusahaan ?? '', nama_kontak: row.nama_kontak ?? '', nomor_telepon: row.nomor_telepon ?? '', alamat: row.alamat ?? '', catatan: row.catatan ?? '', aktif: row.aktif }) }
  return <div className="grid gap-5 md:grid-cols-2"><Panel title={id ? 'Edit Tempat Beli / Sales' : 'Tambah Tempat Beli / Sales'}><ErrorBox>{error}</ErrorBox><form onSubmit={async e => { e.preventDefault(); if (busy) return; setBusy(true); setError(''); try { await api(`/sumber-pembelian${id ? `/${id}` : ''}`, id ? 'PUT' : 'POST', form); setForm(empty); setID(null); await refresh() } catch (err) { setError(message(err)) } finally { setBusy(false) } }}><fieldset disabled={busy} className="space-y-3"><Field label="Nama tempat beli / sales" value={form.nama} onChange={nama => setForm({ ...form, nama })} required /><div className="block text-sm font-semibold"><span>Jenis</span><SearchSelect className={inputClass} value={form.jenis} onValueChange={value => setForm({ ...form, jenis: value })} aria-label="Jenis"><option value="TOKO">Toko</option><option value="SALES">Sales datang ke toko</option></SearchSelect></div>{(['nama_toko_perusahaan', 'nama_kontak', 'nomor_telepon', 'alamat', 'catatan'] as const).map((key, i) => <Field key={key} label={['Toko / perusahaan', 'Kontak', 'Telepon', 'Alamat', 'Catatan'][i]} value={form[key]} onChange={value => setForm({ ...form, [key]: value })} />)}<label className="flex gap-2"><input type="checkbox" checked={form.aktif} onChange={e => setForm({ ...form, aktif: e.target.checked })} />Aktif</label><Button type="submit" disabled={busy}>Simpan Sumber Pembelian</Button>{id && <Button type="button" variant="outline" onClick={() => { setID(null); setForm(empty) }}>Batal edit</Button>}</fieldset></form></Panel><Panel title="Daftar Tempat Beli / Sales"><div className="divide-y">{data.sources.map(row => <div className="flex items-center justify-between gap-3 py-4" key={row.id}><div><strong>{row.nama}</strong><p className="text-sm text-muted-foreground">{row.jenis} · {row.nomor_telepon} {!row.aktif && '· Nonaktif'}</p></div><Button variant="outline" onClick={() => edit(row)}>Edit</Button></div>)}</div></Panel></div>
}
function Payments({ data, refresh }: Props) {
  const empty: Omit<Payment, 'id'> = { nama: '', jenis: 'CASH', tarif_persen: '0', tarif_tetap: '0', penanggung_biaya: 'TOKO', untuk_penjualan: true, untuk_pembelian: false, aktif: true }
  const [form, setForm] = useState(empty); const [id, setID] = useState<number | null>(null); const [error, setError] = useState(''); const [busy, setBusy] = useState(false)
  return <div className="grid gap-5 md:grid-cols-2"><Panel title={id ? 'Edit Metode Pembayaran' : 'Tambah Metode Pembayaran'}><ErrorBox>{error}</ErrorBox><form onSubmit={async e => { e.preventDefault(); if (busy) return; setBusy(true); setError(''); try { await api(`/metode-pembayaran${id ? `/${id}` : ''}`, id ? 'PUT' : 'POST', form); setID(null); setForm(empty); await refresh() } catch (err) { setError(message(err)) } finally { setBusy(false) } }}><fieldset disabled={busy} className="space-y-3"><Field label="Nama metode" value={form.nama} onChange={nama => setForm({ ...form, nama })} required /><div className="block text-sm font-semibold"><span>Jenis</span><SearchSelect className={inputClass} value={form.jenis} onValueChange={value => setForm({ ...form, jenis: value as Payment['jenis'] })} aria-label="Jenis">{['CASH', 'QRIS', 'DEBIT', 'TRANSFER', 'LAINNYA'].map(value => <option key={value}>{value}</option>)}</SearchSelect></div><Field label="Tarif persen" value={form.tarif_persen} type="decimal" onChange={tarif_persen => setForm({ ...form, tarif_persen })} /><Field label="Tarif tetap (Rp)" value={form.tarif_tetap} type="decimal" onChange={tarif_tetap => setForm({ ...form, tarif_tetap })} /><div className="block text-sm font-semibold"><span>Biaya penjualan ditanggung</span><SearchSelect className={inputClass} value={form.penanggung_biaya} onValueChange={value => setForm({ ...form, penanggung_biaya: value as Payment['penanggung_biaya'] })} aria-label="Biaya penjualan ditanggung"><option value="TOKO">Toko</option><option value="PELANGGAN">Pelanggan</option></SearchSelect></div>{(['untuk_penjualan', 'untuk_pembelian', 'aktif'] as const).map((key, i) => <label key={key} className="flex gap-2"><input type="checkbox" checked={form[key]} onChange={e => { setForm({ ...form, [key]: e.target.checked }); setError('') }} />{['Muncul di kasir penjualan', 'Muncul di pembelian', 'Metode aktif'][i]}</label>)}{!form.untuk_penjualan && !form.untuk_pembelian && <p className="text-sm text-muted-foreground" role="status">Metode ini disembunyikan dari penjualan dan pembelian.</p>}<Button type="submit" disabled={busy}>Simpan Metode</Button>{id && <Button type="button" variant="outline" onClick={() => { setID(null); setForm(empty) }}>Batal edit</Button>}</fieldset></form></Panel><Panel title="Daftar Metode Pembayaran"><div className="divide-y">{data.payments.map(row => <div key={row.id} className="flex items-center justify-between gap-3 py-4"><div><strong>{row.nama}</strong><p className="text-sm text-muted-foreground">{row.jenis} · {row.tarif_persen}% + {money(row.tarif_tetap)}</p><p className="text-xs">{row.untuk_penjualan ? 'Penjualan ' : ''}{row.untuk_pembelian ? 'Pembelian ' : ''}{!row.untuk_penjualan && !row.untuk_pembelian ? 'Disembunyikan ' : ''}{!row.aktif && '· Nonaktif'}</p></div><Button variant="outline" onClick={() => { setID(row.id); setForm({ nama: row.nama, jenis: row.jenis, tarif_persen: row.tarif_persen, tarif_tetap: row.tarif_tetap, penanggung_biaya: row.penanggung_biaya, untuk_penjualan: row.untuk_penjualan, untuk_pembelian: row.untuk_pembelian, aktif: row.aktif }) }}>Edit</Button></div>)}</div></Panel></div>
}


export function Inventory({ data, refresh }: Props) {
  const [busy, setBusy] = useState(false); const [error, setError] = useState(''); const [notice, setNotice] = useState('')
  const [stockID, setStockID] = useState(''); const [stockType, setStockType] = useState('AWAL'); const [change, setChange] = useState(''); const [reason, setReason] = useState('')
  const [query, setQuery] = useState('')
  const products = data.products.filter(product => `${product.nama} ${product.sku} ${product.barcode ?? ''}`.toLowerCase().includes(query.trim().toLowerCase()))
  return <div className="mx-auto grid max-w-7xl gap-5 p-5 lg:grid-cols-[360px_1fr]">
    <div className="space-y-3"><ErrorBox>{error}</ErrorBox>{notice && <p role="status">{notice}</p>}
    <Panel title="Stok Awal / Penyesuaian" subtitle="Pembelian baru dicatat lewat menu Pembelian."><form className="space-y-3" onSubmit={async e => { e.preventDefault(); if (busy) return; setBusy(true); setError(''); try { await api(`/produk/${stockID}/mutasi`, 'POST', { jenis: stockType, perubahan: change, catatan: reason }); setChange(''); setReason(''); setNotice('Mutasi stok tersimpan.'); await refresh() } catch (err) { setError(message(err)) } finally { setBusy(false) } }}><div className="block text-sm font-semibold"><span>Produk</span><SearchSelect className={inputClass} value={stockID} onValueChange={value => setStockID(value)} required aria-label="Produk"><option value="">Pilih produk</option>{data.products.filter(p => p.aktif).map(p => <option key={p.id} value={p.id}>{p.nama}</option>)}</SearchSelect></div><SearchSelect className={inputClass} aria-label="Jenis mutasi" value={stockType} onValueChange={value => setStockType(value)}><option value="AWAL">Stok awal (sekali per produk)</option><option value="PENYESUAIAN">Penyesuaian selisih stok</option></SearchSelect><Field label="Perubahan stok (contoh: 10 atau -2)" value={change} onChange={setChange} required /><Field label="Alasan" value={reason} onChange={setReason} required /><Button type="submit" disabled={busy}>Simpan Mutasi</Button></form></Panel>
    </div><Panel title="Stok Produk" subtitle="Saldo stok terkini, termasuk stok negatif dari penjualan.">
      <Field label="Cari stok produk" value={query} onChange={setQuery} />
      <div className="mt-3 divide-y">{products.map(product => <div key={product.id} className="flex items-center justify-between gap-3 py-3"><div><strong>{product.nama}</strong><p className="text-sm text-muted-foreground">{product.sku}</p></div><span className="font-semibold">{data.stocks.find(stock => stock.id === product.id)?.stok ?? '—'} {data.units.find(unit => unit.id === product.satuan_id)?.nama}</span></div>)}</div>
    </Panel>
  </div>
}
