import Decimal from 'decimal.js'
import { APIError } from './api'
import type { DailySnapshot, DailySummaryInput, DailySummaryRecord } from './types'

export function reconcileDailyCash(snapshot: Pick<DailySnapshot, 'total_selesai' | 'total_non_cash' | 'pembelian_cash'>, actual: string, tomorrow: string) {
  const totalExpected = new Decimal(snapshot.total_selesai).minus(snapshot.pembelian_cash)
  const expected = totalExpected.minus(snapshot.total_non_cash)
  const totalActual = new Decimal(actual || 0).plus(snapshot.total_non_cash)
  return { totalExpected, totalActual, expected, difference: totalActual.minus(totalExpected), remaining: new Decimal(actual || 0).minus(tomorrow || 0) }
}

export async function saveDailySummaryAttempt(storage: Pick<Storage, 'getItem' | 'setItem' | 'removeItem'>, key: string, input: DailySummaryInput, send: (body: DailySummaryInput) => Promise<DailySummaryRecord>, onPending: (body: DailySummaryInput | null) => void) {
  const saved = storage.getItem(key)
  const body: DailySummaryInput = saved ? JSON.parse(saved) : input
  storage.setItem(key, JSON.stringify(body)); onPending(body)
  try {
    const result = await send(body)
    storage.removeItem(key); onPending(null)
    return result
  } catch (err) {
    // Backend memeriksa key terlebih dahulu: konflik sumber berarti laporan ini belum tersimpan.
    const staleSource = err instanceof APIError && err.status === 409 && err.message.startsWith('Data transaksi berubah.')
    if (staleSource || (!saved && err instanceof APIError && [400, 403, 404, 409].includes(err.status))) { storage.removeItem(key); onPending(null) }
    throw err
  }
}
